const all = name => { try { return $(name).all().map(item => item.json); } catch { return []; } };
const value = (row, key) => row[key] ?? '';
const idKey = 'content_opportunity_id (ID контент-можливості)';
const scoreKey = 'opportunity_score (Загальна оцінка можливості)';
const evidenceIdsKey = 'evidence_opportunity_ids (ID запитів-доказів)';
const evidenceUrlsKey = 'evidence_urls (Посилання на запити)';
const sources = all('Read Content Opportunities').filter(row => value(row, idKey) && value(row, evidenceIdsKey) && value(row, evidenceUrlsKey));
const used = new Set(all('Read SMM Content Queue').map(row => value(row, 'source_content_opportunity_id')).filter(Boolean));
const profile = all('Read SMM Brand Profile').find(row => value(row, 'status') === 'active');
if (!profile) throw new Error('Не знайдено активний SMM Brand Profile');
return sources.filter(row => !used.has(value(row, idKey))).sort((a, b) => Number(value(b, scoreKey) || 0) - Number(value(a, scoreKey) || 0)).slice(0, 3).map(row => ({ json: {
  source_content_opportunity_id: value(row, idKey),
  source_dedupe_key: value(row, 'dedupe_key (Ключ дедуплікації)'),
  demand_cluster: value(row, 'demand_cluster (Кластер попиту)'),
  client_problem: value(row, 'client_problem (Проблема клієнта)'),
  evidence_opportunity_ids: value(row, evidenceIdsKey),
  evidence_urls: value(row, evidenceUrlsKey),
  technology: value(row, 'technology (Технологія)'),
  technology_fit_rationale: value(row, 'technology_fit_rationale (Чому технологія підходить)'),
  target_audience: value(row, 'target_audience (Цільова аудиторія)'),
  n8n_automation_idea: value(row, 'n8n_automation_idea (Ідея n8n-автоматизації)'),
  solution_architecture: value(row, 'solution_architecture (Архітектура рішення)'),
  potential_service: value(row, 'potential_service (Потенційна послуга)'),
  source_content_angle: value(row, 'content_angle (Контентний кут)'),
  source_hook: value(row, 'hook (Хук)'),
  opportunity_score: Number(value(row, scoreKey) || 0),
  brand: profile,
  batch_id: 'SMM-' + $execution.id
}}));

const schema = { type: 'object', additionalProperties: false, properties: {
  topic: { type: 'string' }, content_angle: { type: 'string' }, target_audience: { type: 'string' },
  cta_keyword: { type: 'string' }, linkedin_post: { type: 'string' }, instagram_caption: { type: 'string' },
  visual_brief: { type: 'string' }
}, required: ['topic', 'content_angle', 'target_audience', 'cta_keyword', 'linkedin_post', 'instagram_caption', 'visual_brief'] };
const brand = $json.brand;
return { json: { ...$json, openai_request: {
  model: 'gpt-5.4-mini', store: false, max_output_tokens: 2300,
  instructions: 'Ти український B2B SMM-стратег для персонального бренду AI-автоматизатора й B2B-інтегратора. Створи один content pack для LinkedIn та Instagram лише на основі source opportunity, evidence і brand profile. Не вигадуй клієнтів, кейси, цифри, результати, сертифікації або можливості технологій. Не називай технологію, якщо її немає у source. Пиши чітко: бізнес-проблема → процес → практичне рішення → CTA. LinkedIn має бути експертним B2B-постом з короткими абзацами; Instagram — коротшим caption з тим самим змістом. CTA повинен вести в LinkedIn DM та використовувати cta_keyword з brand profile. visual_brief — текстовий бриф для каруселі або схеми, без генерації зображень. Поверни тільки JSON за schema.',
  input: JSON.stringify({ source_opportunity: {
    demand_cluster: $json.demand_cluster, client_problem: $json.client_problem, evidence_opportunity_ids: $json.evidence_opportunity_ids,
    evidence_urls: $json.evidence_urls, technology: $json.technology, technology_fit_rationale: $json.technology_fit_rationale,
    target_audience: $json.target_audience, n8n_automation_idea: $json.n8n_automation_idea, solution_architecture: $json.solution_architecture,
    potential_service: $json.potential_service, content_angle: $json.source_content_angle, hook: $json.source_hook, opportunity_score: $json.opportunity_score
  }, brand_profile: { positioning: brand.positioning, primary_audience: brand.primary_audience, services: brand.services, proof_points: brand.proof_points, style_rules: brand.style_rules, avoid_claims: brand.avoid_claims, cta_keyword: brand.cta_keyword, cta_template: brand.cta_template, language: brand.language } }),
  text: { format: { type: 'json_schema', name: 'smm_content_pack', strict: true, schema } }
}}};

const responses = $input.all();
const requests = $('Prepare SMM Request').all();
return responses.map((response, index) => {
  const base = requests[index]?.json;
  if (!base) throw new Error('Не знайдено source opportunity для SMM-відповіді');
  const text = response.json.output?.[0]?.content?.find(part => part.type === 'output_text')?.text;
  if (!text) throw new Error('OpenAI не повернув текст SMM-пакета');
  const idea = JSON.parse(text);
  const now = $now.toISO();
  return { json: {
    smm_content_pack_id: 'SMM::' + base.source_content_opportunity_id,
    source_content_opportunity_id: base.source_content_opportunity_id,
    source_dedupe_key: base.source_dedupe_key,
    batch_id: base.batch_id,
    topic: idea.topic,
    content_angle: idea.content_angle,
    target_audience: idea.target_audience,
    cta_keyword: idea.cta_keyword,
    linkedin_post: idea.linkedin_post,
    instagram_caption: idea.instagram_caption,
    visual_brief: idea.visual_brief,
    review_status: 'needs_review',
    reviewer_note: '',
    ai_model: response.json.model || 'gpt-5.4-mini',
    generated_at: now,
    updated_at: now,
    approved_at: '',
    published_at: '',
    published_url: ''
  }};
});

const responses = $('Generate SMM Content').all();
const usage = responses.reduce((total, item) => {
  const u = item.json.usage ?? {};
  total.input += Number(u.input_tokens ?? 0);
  total.cached += Number(u.input_tokens_details?.cached_tokens ?? 0);
  total.output += Number(u.output_tokens ?? 0);
  total.calls += 1;
  return total;
}, { input: 0, cached: 0, output: 0, calls: 0 });
const totalTokens = usage.input + usage.output;
const estimatedCostUsd = Number(((Math.max(0, usage.input - usage.cached) / 1000000) * 0.75 + (usage.cached / 1000000) * 0.075 + (usage.output / 1000000) * 4.5).toFixed(8));
const now = $now.toISO();
return [{ json: {
  'run_id (ID запуску)': 'SMM-' + $execution.id,
  'n8n_execution_id (ID виконання n8n)': String($execution.id),
  'workflow_name (Назва workflow)': $workflow.name,
  'workflow_category (Категорія workflow)': 'smm_content',
  'trigger_type (Тип запуску)': $execution.mode,
  'started_at (Час початку)': now,
  'finished_at (Час завершення)': now,
  'duration_seconds (Тривалість, сек)': 0,
  'run_status (Статус запуску)': 'success',
  'items_input (Вхідних записів)': responses.length,
  'items_processed (Оброблено записів)': responses.length,
  'items_created (Створено записів)': responses.length,
  'items_updated (Оновлено записів)': 0,
  'items_skipped (Пропущено записів)': 0,
  'items_failed (Помилок записів)': 0,
  'ai_calls (AI-викликів)': usage.calls,
  'model_name (AI-модель)': responses[0]?.json.model ?? 'gpt-5.4-mini',
  'input_tokens (Вхідні токени)': usage.input,
  'output_tokens (Вихідні токени)': usage.output,
  'total_tokens (Усього токенів)': totalTokens,
  'estimated_cost_usd (Орієнтовна вартість, USD)': estimatedCostUsd,
  'error_message (Повідомлення про помилку)': '',
  'run_metadata (Додаткові дані JSON)': JSON.stringify({ cached_input_tokens: usage.cached, pricing_usd_per_million: { input: 0.75, cached_input: 0.075, output: 4.5 }, method: 'OpenAI Responses API actual usage' })
}}];
